// Some portions generated by Claude

// An http(s) IRI in a result table has a ↗ link that opens it in a new tab. Like the copy button beside it, the link
// appears on hover and keyboard focus, and is always shown on touch screens, which cannot hover.
// @ts-check
const { test, expect } = require('@playwright/test');
const {
	createSeededRepository,
	deleteRepository,
	repositoryPageUrl,
	serverBaseUrl,
	uniqueRepositoryId,
	waitForRoute
} = require('./workbench-test-helpers.js');

const REPOSITORY_ID = uniqueRepositoryId('workbench-external-link');
const BSBM_INSTANCES = 'http://www4.wiwiss.fu-berlin.de/bizer/bsbm/v01/instances/';
const QUERY = 'SELECT ?type WHERE { <' + BSBM_INSTANCES + 'ProductType2> '
	+ '<http://www.w3.org/2000/01/rdf-schema#subClassOf> ?type }';

test.describe.configure({ mode: 'serial' });

test.beforeAll(async ({ request }) => {
	await createSeededRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

test.afterAll(async ({ request }) => {
	await deleteRepository(request, serverBaseUrl(), REPOSITORY_ID);
});

const shown = (locator) => locator.evaluate((element) => {
	const style = getComputedStyle(element);
	return style.visibility === 'visible' && Number(style.opacity) === 1;
});

async function runQuery(page) {
	await page.goto(repositoryPageUrl(REPOSITORY_ID, 'query'), { waitUntil: 'domcontentloaded' });
	await waitForRoute(page, 'query');
	await page.locator('#query-page .CodeMirror').first().evaluate((element, query) => element.CodeMirror.setValue(query),
		QUERY);
	await page.locator('#exec').click();
	const cell = page.locator('#query-results .resource').filter({ hasText: 'bsbm-inst:ProductType1' }).first();
	await expect(cell).toBeVisible();
	return cell;
}

test('the external link after an IRI is reached from the keyboard and shown while it has focus', async ({ page }) => {
	await page.setViewportSize({ width: 1280, height: 900 });
	const cell = await runQuery(page);
	const external = cell.locator('a.resourceURL');
	await expect(external).toHaveAccessibleName('Open ' + BSBM_INSTANCES + 'ProductType1 externally');
	await page.mouse.move(0, 0);
	await expect.poll(() => shown(external)).toBe(false);

	await cell.locator('.resource-copy').focus();
	await page.keyboard.press('Tab');

	await expect(external).toBeFocused();
	await expect.poll(() => shown(external)).toBe(true);
});

test('on a touch screen the external link is always shown', async ({ browser, browserName }) => {
	test.skip(browserName === 'firefox', 'Playwright does not support isMobile contexts in Firefox');
	const context = await browser.newContext({ viewport: { width: 1024, height: 900 }, isMobile: true, hasTouch: true });
	const page = await context.newPage();
	try {
		expect(await page.evaluate(() => matchMedia('(hover: none)').matches)).toBe(true);
		const cell = await runQuery(page);

		await expect.poll(() => shown(cell.locator('a.resourceURL'))).toBe(true);
	} finally {
		await context.close();
	}
});
